import{_ as t,o as a,c as _,a4 as s}from"./chunks/framework.CZTQpGgQ.js";const f=JSON.parse('{"title":"2026年全国智慧农业现场推进会在河北雄安召开2026-11-26","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"2026年全国智慧农业现场推进会在河北雄安召开2026-11-26","date":"2026-11-26T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202611/t20261126_6489761.htm","summary":"本网讯　11月23—24日,农业农村部在河北雄安新区召开全国智慧农业现场推进会,研究部署“人工智能+”农业重点工作。农业农村部党组成员、副部长潘文博出席会议并讲话。\\n会议指出,要深入学习领会习近平总书记关于“三农”工作的重要论述和重要指示精神,贯彻落实党中央、国务院关于实施“人工智能+”行动的决策部署,全面推进“人工智能+”农业发展,加快培育农业新质生产力,为加快农业农村现代化提供新动能。\\n...\\n","contentHash":"d8b0c100ae4bc1fc25c9feadc21842b2","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-11-26-2026年全国智慧农业现场推进会在河北雄安召开.md","filePath":"policies/2026-11-26-2026年全国智慧农业现场推进会在河北雄安召开.md"}'),r={name:"policies/2026-11-26-2026年全国智慧农业现场推进会在河北雄安召开.md"};function o(c,e,n,l,p,i){return a(),_("div",null,[...e[0]||(e[0]=[s('<h1 id="_2026年全国智慧农业现场推进会在河北雄安召开2026-11-26" tabindex="-1">2026年全国智慧农业现场推进会在河北雄安召开2026-11-26 <a class="header-anchor" href="#_2026年全国智慧农业现场推进会在河北雄安召开2026-11-26" aria-label="Permalink to &quot;2026年全国智慧农业现场推进会在河北雄安召开2026-11-26&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202611/t20261126_6489761.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-11-26 摘要: 本网讯　11月23—24日,农业农村部在河北雄安新区召开全国智慧农业现场推进会,研究部署“人工智能+”农业重点工作。农业农村部党组成员、副部长潘文博出席会议并讲话。 会议指出,要深入学习领会习近平总书记关于“三农”工作的重要论述和重要指示精神,贯彻落实党中央、国务院关于实施“人工智能+”行动的决策部署,全面推进“人工智能+”农业发展,加快培育农业新质生产力,为加快农业农村现代化提供新动能。 ...</p></blockquote><p>会议指出,要深入学习领会习近平总书记关于“三农”工作的重要论述和重要指示精神,贯彻落实党中央、国务院关于实施“人工智能+”行动的决策部署,全面推进“人工智能+”农业发展,加快培育农业新质生产力,为加快农业农村现代化提供新动能。</p><p>会议强调,今年是“十五五”开局之年,要大力发展智慧农业,加快“人工智能+”农业技术创新、应用场景拓展和产业生态营造,赋能农业科研范式变革、生产经营方式转变、管理服务模式创新。要加快培育高价值应用场景,着力推动农业人工智能技术落地转化;加力破解落地应用的堵点卡点,着力夯实农业人工智能发展底座;激发农业人工智能发展的内生动力,着力构建健康规范的产业生态。</p><p>会议要求,要强化统筹谋划,明确思路方向举措;坚持应用导向,务求取得实际成效;聚焦重点突破,以点带面有序推进;谋划政策工具,做深做实抓手载体。同时,要统筹好发展和安全的关系。</p><p>会上,河北、北京、黑龙江、江苏、广西、新疆等省区农业农村部门负责同志和专家代表作交流发言,中央有关部门负责同志,各省(区、市)、新疆生产建设兵团农业农村部门负责同志,北大荒农垦集团、广东农垦集团负责同志,农业农村部机关司局单位负责同志,以及部分智慧农业专家和企业代表参会。</p><p><a href="https://scs.moa.gov.cn/gzdt/202611/t20261126_6489761.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',7)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
